import { api, requestBody, escapeHtml as esc } from './business-api.mjs';
export async function mountTeamAdmin(root) {
  const section = document.createElement('section'); section.className = 'workspace-panel'; section.id = 'team-admin';
  root.append(section);
  try {
    const data = await api('/api/team-admin');
    section.innerHTML = `<h2>免费组队管理</h2><p>举报待核实，不按数量自动处罚；不得处理本人相关的事件。仅调整组队权限。</p><details><summary>举报记录（${data.reports.filter(r => r.status === 'pending').length} 条待核实）</summary>${data.reports.map(r => `<article class="workspace-panel"><h3>${esc(r.snapshot.room.title)}</h3><p>${esc(r.kind)} · ${esc(({pending:'待核实',verified:'已核实',dismissed:'未成立'})[r.status])}</p><p>${esc(r.reason)}</p><details><summary>查看举报时的招募与消息记录</summary><p>${esc(r.snapshot.room.intro)}</p>${r.snapshot.messages.map(m => `<p>${esc(m.userId)}：${esc(m.text)}</p>`).join('') || '<p>没有可访问的消息记录。</p>'}</details>${r.status === 'pending' ? `<form class="order-form" data-team-command="review" data-id="${esc(r.id)}"><label>核实结果<select name="status"><option value="dismissed">不成立 / 证据不足</option><option value="verified">核实成立</option></select></label><label>核实依据<textarea name="reason" minlength="10" maxlength="300" required></textarea></label><button class="workspace-button">保存核实结果</button></form>` : `<p>${esc(r.decisionReason)}</p>`}${r.status === 'verified' ? `<details><summary>必要时设置组队限制</summary><form class="order-form" data-team-command="restrict" data-report="${esc(r.id)}"><label>限制截止时间<input type="datetime-local" name="expiry" required></label><label>限制依据<textarea name="reason" minlength="10" maxlength="300" required></textarea></label><label>恢复条件<textarea name="recovery" minlength="10" maxlength="300" required></textarea></label><button class="workspace-button">限制新组队与发言</button></form></details>` : ''}</article>`).join('') || '<p>暂无举报。</p>'}</details><details><summary>组队限制与恢复</summary>${data.restrictions.map(r => `<article class="workspace-panel"><p>${esc(r.user_id)} · ${r.active && r.expires_at > Date.now() ? '限制中' : '已恢复或到期'}</p><p>${esc(r.reason)}</p><p>期限至 ${esc(new Date(r.expires_at).toLocaleString('zh-CN'))}；${esc(r.recovery)}</p>${r.active ? `<form class="order-form" data-team-command="restore" data-user="${esc(r.user_id)}"><label>复核与恢复原因<textarea name="reason" minlength="10" maxlength="300" required></textarea></label><button class="workspace-button">恢复组队</button></form>` : ''}</article>`).join('') || '<p>暂无限制。</p>'}</details><details><summary>申诉（${data.appeals.filter(a => a.status === 'pending').length} 条待复核）</summary>${data.appeals.map(a => `<article class="workspace-panel"><p>${esc(a.user_id)}：${esc(a.reason)}</p>${a.status === 'pending' ? `<form class="order-form" data-team-command="appeal" data-id="${esc(a.id)}"><label>复核结果<select name="status"><option value="accepted">通过申诉，解除对应限制</option><option value="rejected">维持对应限制</option></select></label><label>复核理由<textarea name="reason" minlength="10" maxlength="300" required></textarea></label><button class="workspace-button">保存复核结果</button></form>` : `<p>${esc(a.status)}：${esc(a.decision_reason)}</p>`}</article>`).join('') || '<p>暂无申诉。</p>'}</details><p role="status" data-team-admin-error></p>`;
    section.querySelectorAll('form').forEach(form => form.onsubmit = async event => {
      event.preventDefault(); const button = form.querySelector('button'); if (button.disabled) return;
      button.disabled = true;
      const values = Object.fromEntries(new FormData(form));
      const fields = { ...values, ...(form.dataset.id ? { id: form.dataset.id } : {}), ...(form.dataset.user ? { userId: form.dataset.user } : {}), ...(form.dataset.report ? { reportId: form.dataset.report, expiresAt: new Date(values.expiry).getTime() } : {}) };
      const fingerprint = JSON.stringify(fields);
      if (form.dataset.fields !== fingerprint) { form.dataset.fields = fingerprint; form.dataset.request = requestBody({}).requestId; }
      try { await api('/api/team-admin/' + form.dataset.teamCommand, { ...fields, requestId: form.dataset.request }); section.remove(); await mountTeamAdmin(root); }
      catch (error) { section.querySelector('[data-team-admin-error]').textContent = error.message; button.disabled = false; }
    });
  } catch (error) { section.innerHTML = `<h2>免费组队管理</h2><p role="status">${esc(error.message)}</p>`; }
}

